def differByOne(dict):
    # strings are unique, so two words sharing a mask differ in exactly that index
    if len(dict) < 2:
        return False
    for i in range(len(dict[0])):
        masks = set()
        for word in dict:
            masked = word[:i] + '_' + word[i+1:]
            if masked in masks:
                return True
            masks.add(masked)
    return False
